import { test, expect } from '@playwright/test';

const FP_PRIMARY = { 'x-browser-fingerprint': 'qa-detail-hardened-001' };
const FP_SECONDARY = { 'x-browser-fingerprint': 'qa-detail-hardened-002' };

test.describe('SPA Routing & Admin Fix Contracts', () => {
  test('GET /admin, /admin/, and /posts/:id return 200 SPA HTML while API and missing assets return 404', async ({ request }) => {
    for (const spaPath of ['/admin', '/admin/', '/posts/sample-route-check']) {
      const res = await request.get(spaPath);
      expect(res.status()).toBe(200);
      expect(res.headers()['content-type'] || '').toContain('text/html');
      const body = await res.text();
      expect(body).toContain('root');
      expect(body.trim()).not.toBe('Not Found');
    }

    const apiNotFound = await request.get('/api/v1/non-existent-endpoint-check');
    expect(apiNotFound.status()).toBe(404);
    const apiBody = await apiNotFound.json();
    expect(JSON.stringify(apiBody)).toContain('404_NOT_FOUND');

    const missingAsset = await request.get('/assets/non-existent-bundle-99999.js');
    expect(missingAsset.status()).toBe(404);
  });

  test('Admin page opens cleanly on /admin and /admin/, rejects bad credentials, allows login, and stays hidden on public UI', async ({ page }) => {
    await page.goto('/');
    await expect(page.locator('a[href*="/admin"]')).toHaveCount(0);

    await page.goto('/admin');
    await expect(page.getByText(/^Not Found$/i)).toHaveCount(0);
    await expect(page.getByText(/社区系统管理后台|管理员登录/i).first()).toBeVisible();

    const usernameInput = page.getByLabel(/管理员账号/i);
    const passwordInput = page.getByLabel(/管理员密码/i);
    const loginBtn = page.getByRole('button', { name: /登录管理后台|登录/i }).first();

    if (await usernameInput.isVisible()) {
      await usernameInput.fill('admin');
      await passwordInput.fill('wrong-password-check');
      await loginBtn.click();
      await expect(page.getByRole('alert').first()).toBeVisible();

      await usernameInput.fill('admin');
      await passwordInput.fill('admin');
      await loginBtn.click();
    }

    await expect(page.getByText(/平台运行数据概览|Resend 邮件服务与社区配置/i).first()).toBeVisible();

    await page.reload();
    await expect(page.getByText(/^Not Found$/i)).toHaveCount(0);
    await expect(page.getByText(/社区系统管理后台|平台运行数据概览|管理员登录/i).first()).toBeVisible();

    await page.goto('/admin/');
    await expect(page.getByText(/^Not Found$/i)).toHaveCount(0);
    await expect(page.getByText(/社区系统管理后台|平台运行数据概览|管理员登录/i).first()).toBeVisible();
  });
});

test.describe('Post Detail & Comments API Contracts (Hardened)', () => {
  test('GET /api/v1/posts/:id and comments endpoints enforce 404, auth, whitespace, and cross-post parent_id validation', async ({ request }) => {
    const missingPostRes = await request.get('/api/v1/posts/non-existent-post-99999');
    expect(missingPostRes.status()).toBe(404);
    expect(JSON.stringify(await missingPostRes.json())).toContain('404_POST_NOT_FOUND');

    const missingCommentsRes = await request.get('/api/v1/posts/non-existent-post-99999/comments');
    expect(missingCommentsRes.status()).toBe(404);

    const missingClickRes = await request.post('/api/v1/posts/non-existent-post-99999/click');
    expect(missingClickRes.status()).toBe(404);

    const postARes = await request.post('/api/v1/posts', {
      headers: FP_PRIMARY,
      data: { content: `Detail Contract Post A ${Date.now()}` },
    });
    expect([200, 201]).toContain(postARes.status());
    const postA = await postARes.json();

    const postBRes = await request.post('/api/v1/posts', {
      headers: FP_SECONDARY,
      data: { content: `Detail Contract Post B ${Date.now()}` },
    });
    expect([200, 201]).toContain(postBRes.status());
    const postB = await postBRes.json();

    const detailRes = await request.get(`/api/v1/posts/${postA.id}`, { headers: FP_PRIMARY });
    expect(detailRes.status()).toBe(200);
    const detailBody = await detailRes.json();
    expect(detailBody.id).toBe(postA.id);
    expect(Array.isArray(detailBody.images)).toBe(true);
    expect(typeof detailBody.likes_count).toBe('number');
    expect(typeof detailBody.reposts_count).toBe('number');
    expect(typeof detailBody.comments_count).toBe('number');
    expect(typeof detailBody.clicks_count).toBe('number');

    const unauthCommentRes = await request.post(`/api/v1/posts/${postA.id}/comments`, {
      data: { content: 'Unauthorized comment' },
    });
    expect(unauthCommentRes.status()).toBe(401);

    const blankCommentRes = await request.post(`/api/v1/posts/${postA.id}/comments`, {
      headers: FP_PRIMARY,
      data: { content: '   ' },
    });
    expect(blankCommentRes.status()).toBe(400);

    const commentOnBRes = await request.post(`/api/v1/posts/${postB.id}/comments`, {
      headers: FP_SECONDARY,
      data: { content: `Comment on B ${Date.now()}` },
    });
    expect([200, 201]).toContain(commentOnBRes.status());
    const commentOnB = await commentOnBRes.json();

    // Cross-post parent_id must be rejected
    const crossParentRes = await request.post(`/api/v1/posts/${postA.id}/comments`, {
      headers: FP_PRIMARY,
      data: { content: 'Cross post reply attempt', parent_id: commentOnB.id },
    });
    expect([400, 404]).toContain(crossParentRes.status());

    // Non-existent parent_id must be rejected
    const nonexistentParentRes = await request.post(`/api/v1/posts/${postA.id}/comments`, {
      headers: FP_PRIMARY,
      data: { content: 'Missing parent reply attempt', parent_id: 'non-existent-parent-99999' },
    });
    expect([400, 404]).toContain(nonexistentParentRes.status());

    // Valid comment and valid nested reply on Post A
    const topCommentRes = await request.post(`/api/v1/posts/${postA.id}/comments`, {
      headers: FP_PRIMARY,
      data: { content: `Top Comment A ${Date.now()}` },
    });
    expect([200, 201]).toContain(topCommentRes.status());
    const topComment = await topCommentRes.json();

    const nestedReplyRes = await request.post(`/api/v1/posts/${postA.id}/comments`, {
      headers: FP_SECONDARY,
      data: { content: `Nested Reply A ${Date.now()}`, parent_id: topComment.id },
    });
    expect([200, 201]).toContain(nestedReplyRes.status());
    const nestedReply = await nestedReplyRes.json();
    expect(nestedReply.parent_id).toBe(topComment.id);

    const detailAfterRes = await request.get(`/api/v1/posts/${postA.id}`, { headers: FP_PRIMARY });
    expect(detailAfterRes.status()).toBe(200);
    const detailAfter = await detailAfterRes.json();
    expect(detailAfter.comments_count).toBe(2);
  });

  test('Concurrent comments and clicks on the same post preserve uniqueness and atomic counters', async ({ request }) => {
    const seedRes = await request.post('/api/v1/posts', {
      headers: FP_PRIMARY,
      data: { content: `Concurrency Target Post ${Date.now()}` },
    });
    expect([200, 201]).toContain(seedRes.status());
    const { id: postId } = await seedRes.json();

    const commentResponses = await Promise.all(
      Array.from({ length: 5 }, (_, idx) =>
        request.post(`/api/v1/posts/${postId}/comments`, {
          headers: FP_PRIMARY,
          data: { content: `Concurrent Comment ${idx} ${Date.now()}` },
        })
      )
    );
    const commentIds = new Set<string>();
    for (const res of commentResponses) {
      expect([200, 201]).toContain(res.status());
      const body = await res.json();
      expect(typeof body.id).toBe('string');
      commentIds.add(body.id);
    }
    expect(commentIds.size).toBe(5);

    const clickResponses = await Promise.all(
      Array.from({ length: 5 }, () => request.post(`/api/v1/posts/${postId}/click`))
    );
    for (const res of clickResponses) {
      expect(res.status()).toBe(200);
    }

    const detailRes = await request.get(`/api/v1/posts/${postId}`, { headers: FP_PRIMARY });
    expect(detailRes.status()).toBe(200);
    const detail = await detailRes.json();
    expect(detail.comments_count).toBe(5);
    expect(detail.clicks_count).toBe(5);
  });
});

test.describe('Post Detail Page Web E2E (Hardened)', () => {
  test('Comments are moved out of Feed into /posts/:id, feed actions stay on feed, and detail supports commenting, nested replies, likes, reload persistence, and back navigation', async ({ page, request }) => {
    const uniqueTag = Date.now();
    const postText = `Full Detail Flow Post ${uniqueTag}`;
    const seedRes = await request.post('/api/v1/posts', {
      headers: FP_PRIMARY,
      data: { content: postText },
    });
    expect([200, 201]).toContain(seedRes.status());
    const { id: postId } = await seedRes.json();

    await page.goto('/');
    const main = page.getByRole('main');
    const feedCard = main.locator('article').filter({ hasText: postText }).first();
    await expect(feedCard).toBeVisible();

    // Comments must NOT be rendered inline in Feed cards
    await expect(feedCard.getByPlaceholder(/撰写评论|撰写回复/i)).toHaveCount(0);

    // Clicking Like on Feed card must NOT navigate away to detail page
    const feedLikeBtn = feedCard.getByRole('button', { name: /点赞/i }).first();
    await expect(feedLikeBtn).toBeVisible();
    await feedLikeBtn.click();
    expect(page.url()).not.toContain(`/posts/${postId}`);

    // Clicking post text navigates to /posts/:id
    await feedCard.getByText(postText).first().click();
    await expect(page).toHaveURL(new RegExp(`/posts/${postId}/?$`));
    await expect(main.getByText(postText).first()).toBeVisible();

    // Comment form is visible on the detail page
    const commentInput = main
      .getByPlaceholder(/撰写评论|撰写回复|评论|回复/i)
      .or(main.getByRole('textbox', { name: /回复|评论/i }))
      .first();
    await expect(commentInput).toBeVisible();

    const commentForm = main.locator('form').filter({ has: commentInput }).first();
    const submitBtn = commentForm
      .getByRole('button', { name: /回复|发送|提交|评论/i })
      .first();

    // Whitespace comment validation
    await commentInput.fill('   ');
    await submitBtn.click();
    await expect(main.getByText(/不能为空|invalid|required/i).first()).toBeVisible();

    // Post top-level comment
    const topCommentText = `Top Detail Comment ${uniqueTag}`;
    await commentInput.fill(topCommentText);
    await submitBtn.click();
    await expect(main.getByText(topCommentText).first()).toBeVisible();

    // Reply to top-level comment (nested reply)
    const replyTrigger = main
      .locator('.comment-item')
      .filter({ hasText: topCommentText })
      .getByRole('button', { name: /回复/i })
      .or(main.getByRole('button', { name: /^回复$/ }).last())
      .first();
    await expect(replyTrigger).toBeVisible();
    await replyTrigger.click();

    const nestedReplyText = `Nested Detail Reply ${uniqueTag}`;
    await commentInput.fill(nestedReplyText);
    await submitBtn.click();
    await expect(main.getByText(nestedReplyText).first()).toBeVisible();

    // Reload directly on /posts/:id verifies deep-link SPA fallback & persistence
    await page.reload();
    await expect(page).toHaveURL(new RegExp(`/posts/${postId}/?$`));
    await expect(main.getByText(postText).first()).toBeVisible();
    await expect(main.getByText(topCommentText).first()).toBeVisible();
    await expect(main.getByText(nestedReplyText).first()).toBeVisible();

    // Back button returns to Feed (/)
    const backBtn = main.getByRole('button', { name: /返回|back/i }).first();
    await expect(backBtn).toBeVisible();
    await backBtn.click();
    await expect(page).toHaveURL(/^https?:\/\/[^/]+\/?$/);
    await expect(
      main.getByRole('textbox', { name: /发帖|动态|说点什么|post|content/i }).first()
    ).toBeVisible();
  });

  test('Clicking comment button on a Feed card navigates directly to /posts/:id detail page', async ({ page, request }) => {
    const postText = `Comment Button Nav Post ${Date.now()}`;
    const seedRes = await request.post('/api/v1/posts', {
      headers: FP_PRIMARY,
      data: { content: postText },
    });
    const { id: postId } = await seedRes.json();

    await page.goto('/');
    const main = page.getByRole('main');
    const feedCard = main.locator('article').filter({ hasText: postText }).first();
    await expect(feedCard).toBeVisible();

    const commentBtn = feedCard.getByRole('button', { name: /评论|回复/i }).first();
    await commentBtn.click();
    await expect(page).toHaveURL(new RegExp(`/posts/${postId}/?$`));
    await expect(
      main
        .getByPlaceholder(/撰写评论|撰写回复|评论|回复/i)
        .or(main.getByRole('textbox', { name: /回复|评论/i }))
        .first()
    ).toBeVisible();
  });

  test('Visiting non-existent /posts/:id shows graceful 404 state with navigation back to feed', async ({ page }) => {
    await page.goto('/posts/non-existent-post-99999');
    const main = page.getByRole('main');
    await expect(
      main.getByText(/不存在|未找到|找不到|已删除|not found/i).first()
    ).toBeVisible();

    const backHomeBtn = main
      .getByRole('button', { name: /返回|首页|动态/i })
      .or(main.getByRole('link', { name: /返回|首页|动态/i }))
      .first();
    await expect(backHomeBtn).toBeVisible();
    await backHomeBtn.click();
    await expect(page).toHaveURL(/^https?:\/\/[^/]+\/?$/);
  });

  test('Post detail page safely escapes XSS payloads in both post content and comments', async ({ page, request }) => {
    let dialogTriggered = false;
    page.on('dialog', async (dialog) => {
      dialogTriggered = true;
      await dialog.dismiss();
    });

    const marker = Date.now();
    const xssPost = `<img src=x onerror="window.__detailXss=true;alert(1)"> post-xss-safe-${marker}`;
    const seedRes = await request.post('/api/v1/posts', {
      headers: FP_PRIMARY,
      data: { content: xssPost },
    });
    const { id: postId } = await seedRes.json();

    const xssComment = `<svg onload="window.__detailXss=true;alert(2)"> comment-xss-safe-${marker}`;
    await request.post(`/api/v1/posts/${postId}/comments`, {
      headers: FP_PRIMARY,
      data: { content: xssComment },
    });

    await page.goto(`/posts/${postId}`);
    const main = page.getByRole('main');
    await expect(main.getByText(new RegExp(`post-xss-safe-${marker}`)).first()).toBeVisible();
    await expect(main.getByText(new RegExp(`comment-xss-safe-${marker}`)).first()).toBeVisible();
    expect(dialogTriggered).toBe(false);

    const executed = await page.evaluate(
      () => (window as unknown as { __detailXss?: boolean }).__detailXss
    );
    expect(executed).toBeUndefined();
  });

  test('Post detail page renders error state on 500 and recovers on retry', async ({ page, request }) => {
    const postText = `Recovery Detail Post ${Date.now()}`;
    const seedRes = await request.post('/api/v1/posts', {
      headers: FP_PRIMARY,
      data: { content: postText },
    });
    const { id: postId } = await seedRes.json();

    let failDetail = true;
    await page.route(`**/api/v1/posts/${postId}`, async (route) => {
      if (failDetail && route.request().method() === 'GET') {
        await route.fulfill({
          status: 500,
          contentType: 'application/json',
          body: JSON.stringify({ error: '500_DB_ERROR', message: 'Database unavailable' }),
        });
      } else {
        await route.continue();
      }
    });

    await page.goto(`/posts/${postId}`);
    const main = page.getByRole('main');
    await expect(main.getByText(/失败|异常|错误|重试|error/i).first()).toBeVisible();

    failDetail = false;
    const retryBtn = main.getByRole('button', { name: /重试|刷新|retry|reload/i }).first();
    if (await retryBtn.isVisible()) {
      await retryBtn.click();
    } else {
      await page.reload();
    }
    await expect(main.getByText(postText).first()).toBeVisible();
  });
});
